void debug_print_volume_descriptor_information ( iso9660_disk * diskStructure ) { volume_descriptor * tmp = diskStructure -> firstVolumeDescriptor ; char temp [ CD9660_SECTOR_SIZE ] ; printf ( "==Listing Volume Descriptors==\n" ) ; while ( tmp != NULL ) { memcpy ( temp , tmp -> volumeDescriptorData + 1 , 5 ) ; printf ( "Volume descriptor in sector %" PRId64 ": type %i, ID %s\n" , tmp -> sector , tmp -> volumeDescriptorData [ 0 ] , temp ) ; switch ( tmp -> volumeDescriptorData [ 0 ] ) { case 0 : break ; case 1 : break ; case 2 : break ; case 3 : break ; case 255 : break ; } tmp = tmp -> next ; } printf ( "==Done Listing Volume Descriptors==\n" ) ; } 